// Title: C# post‑processing to remove extra spaces from HTML generated by Aspose.Cells
// Common Searches: c# replace multiple spaces in Aspose.Cells HTML output with single space | how to collapse whitespace in HTML saved by Aspose.Cells workbook.Save | regex to clean up redundant spaces in Aspose.Cells generated HTML file | post‑process Aspose.Cells HTML stream to trim extra spaces in C# | remove unnecessary spaces between tags in HTML produced by Aspose.Cells
// Tags: Aspose.Cells HTML whitespace reduction | C# regex post‑process HTML output | Workbook.Save HTML cleanup Aspose.Cells | memory stream HTML conversion Aspose.Cells | collapse spaces in generated HTML C#

using Aspose.Cells;
using System;
using System.IO;
using System.Text.RegularExpressions;

// The example creates a workbook, populates cells, saves it to HTML via a MemoryStream, reads the HTML string, and uses a regular expression to replace sequences of two or more spaces with a single space (optionally removing whitespace between tags), then writes the cleaned HTML to a file.
class Program
{
    static void Main()
    {
        // Create a new workbook (or load an existing one)
        Workbook workbook = new Workbook();

        // Populate some sample data
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Hello");
        sheet.Cells["B1"].PutValue("World");
        sheet.Cells["A2"].PutValue("Aspose");
        sheet.Cells["B2"].PutValue("Cells");

        // Save the workbook to HTML using a memory stream
        using (MemoryStream htmlStream = new MemoryStream())
        {
            workbook.Save(htmlStream, SaveFormat.Html);
            htmlStream.Position = 0;

            // Read the generated HTML as a string
            string htmlContent = new StreamReader(htmlStream).ReadToEnd();

            // Post‑process: replace sequences of multiple spaces with a single space
            string cleanedHtml = Regex.Replace(htmlContent, @"[ ]{2,}", " ");

            // Optionally, you can also trim spaces between tags if needed:
            // cleanedHtml = Regex.Replace(cleanedHtml, @">\s+<", "><");

            // Write the cleaned HTML to a file
            File.WriteAllText("output.html", cleanedHtml);
        }
    }
}
